// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.InputStream;
import java.lang.classfile.ClassFile;
import java.lang.classfile.Opcode;
import java.lang.classfile.instruction.FieldInstruction;
import java.lang.reflect.AccessFlag;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;

import org.eclipse.rdf4j.sail.lmdb.evaluation.codegen.KernelQueryCancelledException;
import org.junit.jupiter.api.Test;

class NativeCancellationTokenTest {
	private static final long FUTURE_TIMEOUT_SECONDS = 5L;

	@Test
	void nonVolatileCancellationStateHasNoPlainFieldAccess() throws Exception {
		byte[] bytecode;
		try (InputStream stream = NativeCancellationToken.class.getResourceAsStream("NativeCancellationToken.class")) {
			assertNotNull(stream, "compiled token bytecode must be available to inspect");
			bytecode = stream.readAllBytes();
		}
		var classModel = ClassFile.of().parse(bytecode);
		var cancellationRequested = classModel.fields().stream()
				.filter(field -> field.fieldName().equalsString("cancellationRequested"))
				.findFirst()
				.orElseThrow(() -> new AssertionError("cancellationRequested field must exist"));

		assertFalse(cancellationRequested.flags().has(AccessFlag.VOLATILE),
				"the cancellation flag should use ordered access instead of volatile field semantics");

		List<String> plainAccesses = new ArrayList<>();
		String tokenClassName = NativeCancellationToken.class.getName().replace('.', '/');
		for (var method : classModel.methods()) {
			for (var element : method.code().stream().flatMap(code -> code.elementStream()).toList()) {
				if (element instanceof FieldInstruction instruction
						&& instruction.owner().asInternalName().equals(tokenClassName)
						&& instruction.name().equalsString("cancellationRequested")) {
					boolean constructorInitialization = method.methodName().equalsString("<init>")
							&& instruction.opcode() == Opcode.PUTFIELD;
					if (!constructorInitialization) {
						plainAccesses.add(method.methodName().stringValue() + " " + instruction.opcode());
					}
				}
			}
		}

		assertTrue(plainAccesses.isEmpty(),
				() -> "nonvolatile cancellation state must not use plain field reads or writes: " + plainAccesses);
	}

	@Test
	void concurrentExplicitRequestsRemainVisibleToAnAlreadyPollingWorker() throws Exception {
		NativeCancellationToken token = new NativeCancellationToken();
		int publisherCount = 2;
		CountDownLatch ready = new CountDownLatch(publisherCount + 1);
		CountDownLatch start = new CountDownLatch(1);
		CountDownLatch polling = new CountDownLatch(1);
		ExecutorService executor = Executors.newFixedThreadPool(publisherCount + 1);
		try {
			Future<KernelQueryCancelledException> observer = executor.submit(() -> {
				ready.countDown();
				awaitStart(start);
				if (token.cancellationPublished()) {
					throw new AssertionError("cancellation must not be published before the observer starts polling");
				}
				polling.countDown();
				long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(FUTURE_TIMEOUT_SECONDS);
				while (System.nanoTime() < deadline) {
					if (token.cancellationPublished()) {
						KernelQueryCancelledException signal = token.pollCancellation();
						if (signal != null) {
							return signal;
						}
					}
					Thread.onSpinWait();
				}
				throw new AssertionError("worker did not observe concurrent explicit cancellation");
			});
			List<Future<?>> publishers = new ArrayList<>(publisherCount);
			for (int i = 0; i < publisherCount; i++) {
				publishers.add(executor.submit(() -> {
					ready.countDown();
					awaitStart(start);
					awaitStart(polling);
					token.requestCancellation();
				}));
			}

			assertTrue(ready.await(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS), "all workers should reach the start gate");
			start.countDown();
			KernelQueryCancelledException signal = observer.get(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS);
			for (Future<?> publisher : publishers) {
				publisher.get(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS);
			}

			assertSame(token, signal.origin());
			assertTrue(signal.observedBy(token));
			assertTrue(token.cancellationPublished());
			assertTrue(token.explicitCancellationPublished());
			assertSame(token, token.pollCancellation().origin(), "explicit cancellation remains terminal");
		} finally {
			start.countDown();
			polling.countDown();
			executor.shutdownNow();
			assertTrue(executor.awaitTermination(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS));
		}
	}

	@Test
	void ancestorCancellationPropagatesWithItsOriginThroughDescendants() {
		NativeCancellationToken evaluation = new NativeCancellationToken();
		NativeCancellationToken child = new NativeCancellationToken(evaluation);
		NativeCancellationToken descendant = new NativeCancellationToken(child);

		evaluation.requestCancellation();

		assertTrue(descendant.cancellationPublished(), "published ancestors are visible to descendants");
		KernelQueryCancelledException signal = descendant.pollCancellation();
		assertSame(evaluation, signal.origin());
		assertTrue(signal.observedBy(descendant));
		assertTrue(descendant.owns(signal));
		assertSame(evaluation, child.pollCancellation().origin());
	}

	@Test
	void localCancellationPropagatesDownItsBranchWithoutCancellingSiblings() {
		NativeCancellationToken evaluation = new NativeCancellationToken();
		NativeCancellationToken local = new NativeCancellationToken(evaluation);
		NativeCancellationToken descendant = new NativeCancellationToken(local);
		NativeCancellationToken sibling = new NativeCancellationToken(evaluation);

		local.requestCancellation();

		KernelQueryCancelledException signal = descendant.pollCancellation();
		assertSame(local, signal.origin());
		assertTrue(signal.observedBy(descendant));
		assertTrue(descendant.owns(signal));
		assertTrue(local.cancellationPublished());
		assertTrue(descendant.cancellationPublished());
		assertFalse(sibling.cancellationPublished());
		assertFalse(sibling.isCancellationRequested());
		assertFalse(evaluation.cancellationPublished());
		assertFalse(evaluation.isCancellationRequested());
	}

	@Test
	void firstLocalCancellationOriginRemainsTerminalWhenAncestorCancelsLater() {
		NativeCancellationToken evaluation = new NativeCancellationToken();
		NativeCancellationToken local = new NativeCancellationToken(evaluation);
		local.requestCancellation();

		assertSame(local, local.pollCancellation().origin());
		evaluation.requestCancellation();

		assertSame(local, local.pollCancellation().origin());
		assertSame(evaluation, evaluation.pollCancellation().origin());
	}

	@Test
	void ownerInterruptRemainsPublishedAfterInterruptIsCleared() {
		NativeCancellationToken evaluation = new NativeCancellationToken();
		boolean wasInterrupted = Thread.interrupted();
		try {
			Thread.currentThread().interrupt();
			assertTrue(evaluation.isCancellationRequested());
			assertTrue(evaluation.cancellationPublished());
			assertTrue(Thread.interrupted(), "the owner interrupt should be cleared after publication");
			assertFalse(Thread.currentThread().isInterrupted());

			assertTrue(evaluation.isCancellationRequested(), "published cancellation survives the cleared interrupt");
			KernelQueryCancelledException signal = evaluation.pollCancellation();
			assertSame(evaluation, signal.origin());
			assertTrue(signal.observedBy(evaluation));
		} finally {
			Thread.interrupted();
			if (wasInterrupted) {
				Thread.currentThread().interrupt();
			}
		}
	}

	private static void awaitStart(CountDownLatch start) {
		try {
			if (!start.await(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS)) {
				throw new AssertionError("worker start gate timed out");
			}
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
			throw new AssertionError("worker interrupted at start gate", e);
		}
	}
}
